"""Deactivate cross-platform records copied by older Douyin cache recovery."""

from collections import defaultdict

from sqlalchemy import Engine, and_, func, or_, select, update
from sqlalchemy.orm import Session, aliased

from app.models.entities import CollectionItemRelation, ContentItem, FavoriteCollection


def deactivate_misclassified_douyin_favorites(engine: Engine) -> tuple[int, int]:
    with Session(engine) as db:
        # These identifiers are generated by Bilibili and Zhihu. Douyin uses numeric work IDs.
        foreign_douyin_items = select(ContentItem.id).where(
            ContentItem.platform == "douyin",
            or_(
                and_(ContentItem.remote_item_id.like("BV%"), func.length(ContentItem.remote_item_id) == 12),
                ContentItem.remote_item_id.like("zhihu:%"),
            ),
        )
        foreign_ids = set(db.scalars(foreign_douyin_items))
        if not foreign_ids:
            return 0, 0

        original = aliased(FavoriteCollection)
        candidates = dict(db.execute(
            select(FavoriteCollection.id, FavoriteCollection.created_at)
            .join(original, and_(
                original.remote_collection_id == FavoriteCollection.remote_collection_id,
                original.title == FavoriteCollection.title,
                original.id < FavoriteCollection.id,
                original.platform.in_(("bilibili", "zhihu")),
            ))
            .where(FavoriteCollection.platform == "douyin", FavoriteCollection.is_active.is_(True))
            .distinct()
        ).all())
        memberships: dict[int, set[int]] = defaultdict(set)
        for collection_id, item_id in db.execute(
            select(CollectionItemRelation.collection_id, CollectionItemRelation.content_item_id).where(
                CollectionItemRelation.collection_id.in_(candidates),
                CollectionItemRelation.is_active.is_(True),
            )
        ):
            memberships[collection_id].add(item_id)

        copied_folders = {collection_id for collection_id, items in memberships.items() if items <= foreign_ids}
        copied_at = {candidates[collection_id] for collection_id in copied_folders}
        # An empty copy has no member IDs. Require creation in the same batch as a confirmed copy.
        copied_folders.update(
            collection_id for collection_id, created_at in candidates.items()
            if collection_id not in memberships and created_at in copied_at
        )

        db.execute(update(FavoriteCollection).where(
            FavoriteCollection.id.in_(copied_folders),
        ).values(is_active=False))
        db.execute(update(CollectionItemRelation).where(
            CollectionItemRelation.is_active.is_(True),
            or_(
                CollectionItemRelation.collection_id.in_(copied_folders),
                CollectionItemRelation.content_item_id.in_(foreign_douyin_items),
            ),
        ).values(is_active=False))
        changed_items = db.execute(update(ContentItem).where(
            ContentItem.is_active.is_(True), ContentItem.id.in_(foreign_douyin_items),
        ).values(is_active=False)).rowcount
        db.commit()
        return len(copied_folders), changed_items
